INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('28c246c2a0453025bad5','AMEDEX 2025 Emergency Medicine 1.pdf','242','Emergency Medicine','A 42-year-old woman sustained a motor vehicle
accident (MVA) 2 days ago and was brought to
the Emergency Department by ambulance. She
was resuscitated accordingly, and was admitted
to the hospital due to fractures of ribs and her
left humerus. Today, she is found to be in
respiratory distress. Pulse oxymetry shows
oxygen saturation of 89% on room air. She has
a blood pressure of 130/85 mmHg, pulse rate of
100bpm in both arms, respiratory rate of 30
breaths per minute, and a temperature of
36./°C. Lungs and heart are clear on
auscultation. Supplemental oxygen by facial
mask is started, and a chest X-ray obtained that
