INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b3ced7823164c1463a82','AMEDEX 2025 Emergency Medicine 1.pdf','259','Emergency Medicine','A 36-year-old man is rushed into the
Emergency Department by paramedics after
he sustained a head-on collision as an
unrestrained driver. He has a hard collar and
his head is fixed to a spine board. On a quick
review, he is conscious and fully oriented, but
in distress as he is not able to feel his arms
and legs. There is no visible site of active
bleeding or limb deformity. Chest is clear to
auscultation, neck veins are not raised, and
abdominal exam is inconclusive. His blood
pressure is 90/40 mmHg, heart rate 50 bpm
and respiratory rate 18 breath per minute.
His oxygen saturation is 88% on room air.
Sphincter tone is decreased and there is no
sensation or deep tendon reflexes below the
neck. He is immediately placed on
Supplemental oxygen via face mask. Which
one of the following would be the most
