INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d28effdee391001f6369','AMEDEX 2025 Endo_ breast 1-50.pdf','1','Endocrine/Breast','ONT dsIZE: OF - .
Benjamin is 65 years old and a regular patient
in your GP clinic. He has presented with a
complaint of left breast enlargement for the past
three months. He has congestive heart failure
(CHF), diagnosed two years ago, for which he
was Started on metoprolol, captopril, and
digoxin. He developed ankle edema, nocturnal
cough, and exertional dyspnea four months
ago. Based on the diagnosis of CHF
decompensation, spironolactone was added to
his medications with adequate control of his
symptoms. He does not smoke, nor does he
drink alcohol. His family history is significant for
breast cancer in his mother at the age of 58
years and in his sister at the age of 50 years.
On examination, a tender round, rubbery mass
4x3 cm in size and concentric with the left
