INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b65262a9391e87f102fc','AMEDEX 2025 Endo_ breast 1-50.pdf','30','Endocrinology/Breast','Daniel, a 78-year-old patient of yours, presents for consultation. He had a fall last month and had his femoral neck fractured. He underwent surgery and intramedullary nail placement. The fracture occurred when the chair leg broke, and he fell from a height of approximately 70 cm. In laboratory assessment, significant findings are a testosterone level of 8 ng/dL and vitamin D of 12 mmol/L. Serum calcium and other laboratory parameters, including liver and renal function tests, are normal. Which of the following is the most important management to consider as the next step?','{"A":"Alendronate 70 mg, once weekly.","B":"Calcium 1000 mg daily plus vitamin D 600 IU daily.","C":"Calcitriol 0.25 mg daily.","D":"Testosterone replacement therapy.","E":"Adequate sun exposure."}','C','Option C Is correct

The femoral neck fracture caused by falling off a
Short chair, as described, is, in fact, a fracture
following a minor (low) trauma. This is always
pathologic. Osteoporosis is the most common
cause of pathologic fractures. Unlike in women,
osteoporosis in men is almost always secondary
and a manifestation of an underlying disease.
Therefore, in men with clinical manifestations of
osteoporosis, e.g., low trauma fracture or with
low bone mass by DEXA (T-score less than -2.0),
an initial evaluation for secondary causes of
osteoporosis should be performed.

Conditions to consider are renal or liver disease,
hyperparathyroidism, Cushing''s syndrome,
celiac disease, and other forms of
malabsorption or hypercalciuria.

The initial evaluation should include routine
biochemical tests for renal or hepatic disease, a
full blood exam (FBE), serum testosterone,
calcium, alkaline phosphatase, 25-
hydroxyvitamin D , and 24-hour urine cortisol.

Based on the test results, Daniel suffers from
severe vitamin D deficiency, and vitamin D
Should be replenished as the most appropriate
next step in management. The treatment option
of choice is calcitriol 0.25mg daily.

«Option A) Bisphosphonates are medicatio

choice for the treatment of osteoporosis and

(Option A) Bisphosphonates are medications of

choice for the treatment of osteoporosis and
prevention of further fractures in patients with
osteoporosis, whose osteoporosis is not due to
hypogonadism (low testosterone levels), or
those with hypogonadism in whom testosterone
replacement therapy is contraindicated.
Indications are a T-score of less than -2.5 or a
history of pathologic fracture regardless of the
T-score. The two most widely used drugs are
alendronate and risedronate. Alendronate
should be given 70 mg, weekly (or 10mg, daily).
It is, however, necessary that vitamin D be
corrected to a level of above 50nmol/L before
therapy with bisphosphonates is started.

(Option B)This patient has normal serum
calcium levels and does not need calcium
Supplementation. Moreover, calcium should not
be added to calcitriol therapy due to the risk of
hypercalcemia. Dietary calcium intake should be
maintained at 800 to 1000 mg daily.

(Option D) Testosterone replacement therapy is
the treatment of choice in osteoporotic men
with hypogonadism. Daniel’s testosterone level
is in the lower limit normal range. Judged by his
testosterone level, he is unlikely to have
hypogonadism.

(Option E) Adequate sun exposure should be
recommended to all patients to prevent vitamin
D deficiency. Daniel has severe vitamin D

deficiency and needs to be treated more

ageressively ratemtamiiee wi reun exposure.','{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Endo_ breast 1-50.pdf","supporting_pages":[30,31,32,33,34],"source_qid":null,"duplicate_group_id":null,"duplicate_sources":[],"parser_version":"manual-review-batch004-2026-09-24","parser_mode":"human_visual_review_batch004","text_method":"manual_visual_plus_context","visual_asset":null,"asset_preview_url":null}',NULL,NULL,'text',NULL,'needs_verification','[]','high','{"record_id":"b65262a9391e87f102fc","record_type":"text_mcq","source_file":"AMEDEX 2025 Endo_ breast 1-50.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Endo_ breast 1-50.pdf","source_year":2025,"source_page":30,"supporting_pages":[30,31,32,33,34],"source_qid":null,"domain_hint":"Endocrinology/Breast","stem":"Daniel, a 78-year-old patient of yours, presents for consultation. He had a fall last month and had his femoral neck fractured. He underwent surgery and intramedullary nail placement. The fracture occurred when the chair leg broke, and he fell from a height of approximately 70 cm. In laboratory assessment, significant findings are a testosterone level of 8 ng/dL and vitamin D of 12 mmol/L. Serum calcium and other laboratory parameters, including liver and renal function tests, are normal. Which of the following is the most important management to consider as the next step?","options":{"A":"Alendronate 70 mg, once weekly.","B":"Calcium 1000 mg daily plus vitamin D 600 IU daily.","C":"Calcitriol 0.25 mg daily.","D":"Testosterone replacement therapy.","E":"Adequate sun exposure."},"options_mode":"text","source_answer":"C","source_explanation":"Option C Is correct\n\nThe femoral neck fracture caused by falling off a\nShort chair, as described, is, in fact, a fracture\nfollowing a minor (low) trauma. This is always\npathologic. Osteoporosis is the most common\ncause of pathologic fractures. Unlike in women,\nosteoporosis in men is almost always secondary\nand a manifestation of an underlying disease.\nTherefore, in men with clinical manifestations of\nosteoporosis, e.g., low trauma fracture or with\nlow bone mass by DEXA (T-score less than -2.0),\nan initial evaluation for secondary causes of\nosteoporosis should be performed.\n\nConditions to consider are renal or liver disease,\nhyperparathyroidism, Cushing''s syndrome,\nceliac disease, and other forms of\nmalabsorption or hypercalciuria.\n\nThe initial evaluation should include routine\nbiochemical tests for renal or hepatic disease, a\nfull blood exam (FBE), serum testosterone,\ncalcium, alkaline phosphatase, 25-\nhydroxyvitamin D , and 24-hour urine cortisol.\n\nBased on the test results, Daniel suffers from\nsevere vitamin D deficiency, and vitamin D\nShould be replenished as the most appropriate\nnext step in management. The treatment option\nof choice is calcitriol 0.25mg daily.\n\n«Option A) Bisphosphonates are medicatio\n\nchoice for the treatment of osteoporosis and\n\n(Option A) Bisphosphonates are medications of\n\nchoice for the treatment of osteoporosis and\nprevention of further fractures in patients with\nosteoporosis, whose osteoporosis is not due to\nhypogonadism (low testosterone levels), or\nthose with hypogonadism in whom testosterone\nreplacement therapy is contraindicated.\nIndications are a T-score of less than -2.5 or a\nhistory of pathologic fracture regardless of the\nT-score. The two most widely used drugs are\nalendronate and risedronate. Alendronate\nshould be given 70 mg, weekly (or 10mg, daily).\nIt is, however, necessary that vitamin D be\ncorrected to a level of above 50nmol/L before\ntherapy with bisphosphonates is started.\n\n(Option B)This patient has normal serum\ncalcium levels and does not need calcium\nSupplementation. Moreover, calcium should not\nbe added to calcitriol therapy due to the risk of\nhypercalcemia. Dietary calcium intake should be\nmaintained at 800 to 1000 mg daily.\n\n(Option D) Testosterone replacement therapy is\nthe treatment of choice in osteoporotic men\nwith hypogonadism. Daniel’s testosterone level\nis in the lower limit normal range. Judged by his\ntestosterone level, he is unlikely to have\nhypogonadism.\n\n(Option E) Adequate sun exposure should be\nrecommended to all patients to prevent vitamin\nD deficiency. Daniel has severe vitamin D\n\ndeficiency and needs to be treated more\n\nageressively ratemtamiiee wi reun exposure.","source_answer_status":"source_revealed","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"human_visual_review_batch004","text_method":"manual_visual_plus_context","parser_version":"manual-review-batch004-2026-09-24","visual_asset":null,"manual_review_batch":"004","manual_review_source_key":"","stem_hash":"3956e08a2338134177942e0f81934705a2e2df03b378d431b29f4cf1a91ca421"}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
