INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('76172ce463d85f580300','AMEDEX 2025 Endo_ breast 1-50.pdf','72','Endocrine/Breast','A 30-year-old man presents to your practice
with complaints of anxiety and palpitation. He
mentions that he is always afraid that
something bad will happen soon. On
examination, he has a blood pressure of
160/80mMmHg and a heart rate of 110bpm.
His palms are wet. Which one of the following
