INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e6b681cdf03947bb1926','AMEDEX 2025 Endo_ breast 1-50.pdf','161','Endocrine/Breast','A 55-year-old woman presents to your
practice after noticing a clear nipple
discharge from her right breast. On physical
examination, no palpable mass is found in
her breasts. Both nipples appear normal;
however, pressure over the right areola
