INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8a74fbcf9bbcda3ea070','AMEDEX 2025 Endo_ breast 1-50.pdf','210','Endocrine/Breast','Lucas is a 67-year-old patient of yours in your
GP clinic. He has congestive heart failure (CHF)
diagnosed three years ago, for which he has
been on carvedilol, perindopril, and digoxin with
improvement in symptoms. Six months ago, due
to decompensation of his CHF, evident by
increased dyspnea and ankle edema, and after
specialist advice, he was started on
spironolactone. Today, he has presented with a
complaint of painful unilateral breast
enlargement. He does not smoke and drinks
only on social occasions and within safe limits.
His past medical history, besides the CHF, is a
myocardial infarction seven years ago. His
family history is remarkable for breast cancer in
his mother, who died 15 years ago, and in his
sister at the age of 52. On examination, you
notice a left breast lump concentric with the
nipple, which is firm, rubbery, and slightly
tender. There is no nipple discharge, ulceration,
or regional lymphadenopathy. The other breast
is normal. Which of the following could be the
most likely cause of this presentation?','{"A":"Breast cancer.","B":"Digoxin.","C":"Spironolactone.","D":"Carvedilol.","E":"Perindopril."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Endo_ breast 1-50.pdf","supporting_pages":[210,211],"source_qid":null,"duplicate_group_id":"exact-8f8e7c47f926","duplicate_sources":[{"record_id":"8a74fbcf9bbcda3ea070","record_type":"text_mcq","source_file":"AMEDEX 2025 Endo_ breast 1-50.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Endo_ breast 1-50.pdf","source_page":210,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8a74fbcf9bbcda3ea070","source_file":"AMEDEX 2025 Endo_ breast 1-50.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Endo_ breast 1-50.pdf","source_year":2025,"source_page":210,"supporting_pages":[210,211],"source_qid":null,"domain_hint":"Endocrine/Breast","stem":"Lucas is a 67-year-old patient of yours in your\nGP clinic. He has congestive heart failure (CHF)\ndiagnosed three years ago, for which he has\nbeen on carvedilol, perindopril, and digoxin with\nimprovement in symptoms. Six months ago, due\nto decompensation of his CHF, evident by\nincreased dyspnea and ankle edema, and after\nspecialist advice, he was started on\nspironolactone. Today, he has presented with a\ncomplaint of painful unilateral breast\nenlargement. He does not smoke and drinks\nonly on social occasions and within safe limits.\nHis past medical history, besides the CHF, is a\nmyocardial infarction seven years ago. His\nfamily history is remarkable for breast cancer in\nhis mother, who died 15 years ago, and in his\nsister at the age of 52. On examination, you\nnotice a left breast lump concentric with the\nnipple, which is firm, rubbery, and slightly\ntender. 