INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('506921f681dd0a720dd2','AMEDEX 2025 Ethics file 1.pdf','15','Ethics/Population Health','Glen is a 32-years old patient of yours who has
been recently found out to be HIV positive.
Maggie, his wife, is also a patient in your office.
In the last visit and after telling Glen about his
diagnosis and counseling him about treatment
options and preventive measures, you advised
that he should tell her wife about his diagnosis
and that she needs HIV testing, and if positive,
treatment. Despite full explanations about the
risks to his wife and the methods to inform her,
he still refuses to tell his wife because he
believes this could ruin their marriage and that
he cannot afford to lose her in such a situation.
You again explain to him that it is necessary for
her good. He still refuses. Which one of the
following would be the most appropriate next
step in management?','{"A":"Inform health authorities.","B":"Inform his wife.","C":"Respect his confidentiality.","D":"Tell him that she should practice safe\nsex as of now.","E":"Apply for a court order for\nnotification."}',NULL,NULL,'{"source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","supporting_pages":[15,16],"source_qid":null,"duplicate_group_id":"exact-300abaca10ee","duplicate_sources":[{"record_id":"506921f681dd0a720dd2","record_type":"text_mcq","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_page":15,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"v27_cross_page_option_stitch","text_method":"tesseract_retry_200dpi_psm3","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"506921f681dd0a720dd2","source_file":"AMEDEX 2025 Ethics file 1.pdf","source_relative_path":"AMEDEX 2025.09更新包/AMEDEX 2025 Ethics file 1.pdf","source_year":2025,"source_page":15,"supporting_pages":[15,16],"source_qid":null,"domain_hint":"Ethics/Population Health","stem":"Glen is a 32-years old patient of yours who has\nbeen recently found out to be HIV positive.\nMaggie, his wife, is also a patient in your office.\nIn the last visit and after telling Glen about his\ndiagnosis and counseling him about treatment\noptions and preventive measures, you advised\nthat he should tell her wife about his diagnosis\nand that she needs HIV testing, and if positive,\ntreatment. Despite full explanations about the\nrisks to his wife and the methods to inform her,\nhe still refuses to tell his wife because he\nbelieves this could ruin their marriage and that\nhe cannot afford to lose her in such a situation.\nYou again explain to him that it is necessary for\nher good. He still refuses. Which one of the\nfollowing would be the most appropriate next\nstep in management?","options":{"A":"Info